// Source: master-workflow-v115.js
(()=>{
'use strict';
if(window.BOS_MASTER_WORKFLOW_V115)return;
window.BOS_MASTER_WORKFLOW_V115=true;
const API_URL='https://obsropbslfwtanyspjbi.supabase.co/functions/v1/master-workflow-api';
let busy=false,queued=false;
const escv=v=>typeof esc==='function'?esc(v):String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const masterMode=()=>String(state?.user?.role||'')==='master'||(typeof isMasterPreview==='function'&&isMasterPreview())||(typeof liveMasterMode==='function'&&liveMasterMode());
const liveMaster=()=>String(state?.user?.role||'')==='master';
const dispatcherMode=()=>String(state?.user?.role||'')==='dispatcher'||(typeof isDispatcherPreview==='function'&&isDispatcherPreview());
const orderById=id=>(state?.orders||[]).find(o=>String(o.id)===String(id))||null;
const stageOf=o=>{if(String(o?.status||'')==='Выполнена')return'completed';if(String(o?.status||'')==='Отменена')return'cancelled';const s=String(o?.master_workflow_stage||'assigned');return s==='arrived'?'departed':['assigned','departed','started'].includes(s)?s:'assigned'};
const laterAssigned=o=>['departed','started','completed'].includes(stageOf(o))||!!o?.report_uploaded_at;
const laterDeparted=o=>['started','completed'].includes(stageOf(o))||!!o?.report_uploaded_at;
const calledDone=o=>!!o?.master_called_at||laterAssigned(o);
const agreementDone=o=>!!o?.master_agreed_at||laterAssigned(o);
const reportUploaded=o=>!!o?.report_uploaded_at||!!o?.report_act_url;
const reportRejected=o=>String(o?.report_review_status||'')==='rejected';
const reportApproved=o=>String(o?.status||'')==='Выполнена'||String(o?.report_review_status||'')==='approved';
const active=o=>o&&!['Выполнена','Отменена'].includes(String(o.status||''));
const hasSchedule=o=>!!String(o?.scheduled_date||'').slice(0,10)&&!!String(o?.scheduled_time||o?.time_slot||'').slice(0,5);
const phoneHref=v=>{let p=String(v||'').trim().replace(/[^\d+]/g,'');if(/^8\d{10}$/.test(p))p='+7'+p.slice(1);else if(/^\d{10}$/.test(p))p='+7'+p;return p};
const fmt=v=>{if(!v)return'';const d=new Date(v);return Number.isNaN(d.getTime())?'':d.toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})};
const whenText=o=>`${String(o?.scheduled_date||'').slice(0,10)||'Дата не назначена'}${String(o?.scheduled_time||o?.time_slot||'').slice(0,5)?` · ${String(o?.scheduled_time||o?.time_slot||'').slice(0,5)}`:''}`;
async function authHeaders(){const h=window.BOS_AUTH_HEADERS?await window.BOS_AUTH_HEADERS():{};return {...h,'Content-Type':'application/json'}}
async function workflowCall(action,id,payload={}){const r=await fetch(API_URL,{method:'POST',headers:await authHeaders(),body:JSON.stringify({action,id,...payload})});const d=await r.json().catch(()=>({}));if(!r.ok||!d.ok)throw new Error(d.error||'Не удалось сохранить действие');return d}
function mergeOrder(id,data){const i=(state.orders||[]).findIndex(o=>String(o.id)===String(id));if(i>=0)state.orders[i]={...state.orders[i],...(data||{})}}
function msg(id,text){const p=document.querySelector('#modalRoot .bosMasterWorkflow');if(String(p?.dataset?.orderId||'')!==String(id))return;const el=p.querySelector('.mwv2Msg');if(el)el.textContent=text||''}
function status(o){if(String(o?.status||'')==='Отменена')return'Отменена';if(reportApproved(o))return'Завершена';if(reportRejected(o))return'Отчёт на доработку';if(reportUploaded(o))return'Отчёт на проверке';if(stageOf(o)==='started')return'В работе';if(stageOf(o)==='departed')return'В дороге';if(agreementDone(o))return'Договорено';if(calledDone(o))return window.BOS_CONTACT_STATUS?.confirmed(o)?'Связался':'Звонок отмечен';return'Нужно позвонить'}
function steps(o){const stage=stageOf(o),raw=[['Звонок',calledDone(o),fmt(o?.master_called_at)],['Договорённость',agreementDone(o),fmt(o?.master_agreed_at)],['Выехал',['departed','started','completed'].includes(stage)||reportUploaded(o),fmt(o?.master_departed_at)],['Работа',laterDeparted(o),fmt(o?.master_started_at)],['Отчёт',reportUploaded(o),fmt(o?.report_uploaded_at)],['Завершена',reportApproved(o),fmt(o?.completed_at)]],pending=raw.findIndex(x=>!x[1]);return raw.map((x,i)=>({label:x[0],done:x[1],at:x[2],current:pending===i||(pending<0&&i===raw.length-1)}))}
function refresh(id=''){decorateMasterModal(id);decorateToday();decorateDispatcher()}
window.masterWorkflowMarkCalled=async function(id){if(!liveMaster()||busy)return;const o=orderById(id);if(!active(o)||calledDone(o))return;busy=true;msg(id,'Сохраняем звонок…');try{const d=await workflowCall('markCalled',id,{contact_confirmed:true});mergeOrder(id,d.order);refresh(id)}catch(e){msg(id,e?.message||String(e))}finally{busy=false}};
window.masterWorkflowConfirmAgreement=async function(id){if(!liveMaster()||busy)return;const o=orderById(id);if(!active(o)||agreementDone(o))return;busy=true;msg(id,'Подтверждаем договорённость…');try{const d=await workflowCall('confirmAgreement',id);mergeOrder(id,d.order);refresh(id)}catch(e){msg(id,e?.message||String(e))}finally{busy=false}};
window.masterWorkflowAgreementStep=function(id){const o=orderById(id);if(!o||!liveMaster())return;if(!calledDone(o)){msg(id,'Сначала позвоните клиенту и отметьте звонок');return}if(hasSchedule(o))return window.masterWorkflowConfirmAgreement(id);if(typeof window.openMasterAgreement==='function')return window.openMasterAgreement(id);msg(id,'Форма договорённости недоступна')};
const previousSetStage=window.masterWorkflowSetStage;
if(typeof previousSetStage==='function')window.masterWorkflowSetStage=function(id,stage){const o=orderById(id);if(stage==='departed'&&o&&!agreementDone(o)){msg(id,'Сначала подтвердите договорённость с клиентом');return}return previousSetStage.apply(this,arguments)};
function actions(o,preview){if(preview||!liveMaster()||!active(o))return'';const called=calledDone(o),agreed=agreementDone(o),stage=stageOf(o),href=phoneHref(o.phone||o.client_phone),call=href?`<a class="secondary mwv2CallLink bosMwCallAction" href="tel:${escv(href)}">Позвонить клиенту</a>`:'',move=`<button type="button" class="secondary" onclick="masterWorkflowOpenReschedule('${escv(o.id)}')">Нужно перенести</button>`;if(!called)return `${call||'<span class="muted mwv2NoPhone">Телефон клиента не указан</span>'}${href?`<button type="button" class="primary" onclick="masterWorkflowMarkCalled('${escv(o.id)}')">Связался с клиентом</button>`:''}${move}`;if(!agreed)return `${call}<div class="mwv2AgreementSummary"><span>Текущая дата и время</span><b>${escv(whenText(o))}</b></div><button type="button" class="primary" onclick="masterWorkflowAgreementStep('${escv(o.id)}')">${hasSchedule(o)?'Подтвердить договорённость':'Указать дату и время'}</button>${move}`;if(stage==='assigned')return `${call}<button type="button" class="primary" onclick="masterWorkflowSetStage('${escv(o.id)}','departed')">Выехал</button>${move}`;if(stage==='departed')return `${call}<button type="button" class="primary" onclick="masterWorkflowSetStage('${escv(o.id)}','started')">Работа начата</button>${move}`;if(stage==='started'&&!reportUploaded(o))return `${call}<button type="button" class="primary mwv2ReportBtn" onclick="masterWorkflowComplete('${escv(o.id)}')">Завершить и прикрепить отчёт</button>${move}`;if(reportRejected(o))return `<button type="button" class="primary mwv2ReportBtn" onclick="masterWorkflowComplete('${escv(o.id)}')">Исправить отчёт</button>${move}`;if(reportUploaded(o)&&!reportApproved(o))return '<div class="mwv2Review"><b>Отчёт отправлен</b><span>Ожидает проверки диспетчером или руководителем.</span></div>';return''}
function rejectionNotice(o){return reportRejected(o)?`<div class="mwv2Review rejected"><b>Отчёт на доработке</b><span>${escv(o.report_review_comment||'Уточните причину у диспетчера.')}</span>${!reportUploaded(o)?'<span>Этапы заявки начаты заново. Пройдите их по порядку перед повторным отчётом.</span>':''}</div>`:''}
function panelHtml(o){const preview=masterMode()&&!liveMaster(),s=status(o);return `<div class="mwv2Head"><div><small>РАБОЧИЙ ПРОЦЕСС</small><h3>${escv(s)}</h3></div><span>${escv(s)}</span></div><div class="mwv2Steps">${steps(o).map(x=>`<div class="mwv2Step${x.done?' done':''}${x.current?' current':''}"><i></i><b>${escv(x.label)}</b>${x.at?`<small>${escv(x.at)}</small>`:''}</div>`).join('')}</div>${preview?'<p class="muted">В режиме просмотра действия недоступны.</p>':''}${rejectionNotice(o)}<div class="mwv2Actions">${actions(o,preview)}</div><p class="muted mwv2Msg"></p>`}
function decorateMasterModal(forceId=''){if(!masterMode())return;const modal=document.querySelector('#modalRoot .modal');if(!modal||modal.querySelector('#masterReportForm,#masterAgreementForm,#masterRescheduleForm'))return;const panel=modal.querySelector('.bosMasterWorkflow'),id=String(forceId||panel?.dataset?.orderId||modal.dataset.bosWorkflowOrderId||''),o=orderById(id);if(!panel||!o)return;const sig=JSON.stringify([o.id,o.status,o.master_called_at,o.master_agreed_at,o.master_workflow_stage,o.master_departed_at,o.master_started_at,o.report_uploaded_at,o.report_review_status,o.report_review_comment,o.completed_at,o.scheduled_date,o.scheduled_time,o.time_slot]);if(panel.dataset.mwv2Sig===sig&&panel.querySelector('.mwv2Head'))return;panel.dataset.mwv2Sig=sig;panel.dataset.bosV115='1';panel.innerHTML=panelHtml(o)}
function decorateToday(){if(!masterMode())return;document.querySelectorAll('.bosMwTodayCard').forEach(card=>{const m=String(card.getAttribute('onclick')||'').match(/openOrder\(['"]([^'"]+)/);if(!m)return;const o=orderById(m[1]);if(!o)return;let chip=card.querySelector('.mwv2TodayStage');if(!chip){chip=document.createElement('span');chip.className='mwv2TodayStage';const legacy=card.querySelector('.bosMwTodayStage');if(legacy)legacy.insertAdjacentElement('afterend',chip);else card.appendChild(chip)}const text=status(o);if(chip.textContent!==text)chip.textContent=text})}
function orderIdFromCard(card){const direct=card?.dataset?.orderId;if(direct)return String(direct);const m=String(card?.getAttribute?.('onclick')||'').match(/openOrder\(['"]([^'"]+)/);return m?String(m[1]):''}
function setChip(card,selector,text,target){let chip=card.querySelector(selector);if(!chip){chip=document.createElement('span');chip.className=selector.slice(1);(target(card)||card).appendChild(chip)}if(chip.textContent!==text)chip.textContent=text;return chip}
function decorateDispatcherCards(){if(!dispatcherMode())return;document.querySelectorAll('[data-order-id].dbOrderCard,[data-order-id].dbV23Card,[data-order-id].dbV24Card').forEach(card=>{const o=orderById(card.dataset.orderId);if(!o)return;const text=status(o),chip=setChip(card,'.mwv2FieldStageChip',text,c=>c.querySelector('.dbV24Badges'));chip.classList.toggle('danger',text==='Нужно позвонить'||text==='Отчёт на доработку')});document.querySelectorAll('.opsCompactOrder,.dmv2Order').forEach(card=>{const o=orderById(orderIdFromCard(card));if(o)setChip(card,'.mwv2MobileStage',status(o),c=>c.querySelector('.opsCompactBottom,.dmv2OrderTop'))})}
function flowHtml(o){return `<b>Рабочий процесс мастера</b><div>${steps(o).map(x=>`<span class="${x.done?'done':x.current?'current':''}">${escv(x.label)}</span>`).join('')}</div>`}
function decorateDispatcherDetail(){if(!dispatcherMode())return;const detail=document.querySelector('#dispatchBoardDetail .dbDetail,.ddDetail');if(!detail)return;const selected=document.querySelector('.dbOrderCard.selected,.ddQueueCard.isSelected'),o=orderById(selected?.dataset?.orderId||'');if(!o)return;const sig=JSON.stringify([o.id,o.status,o.master_called_at,o.master_agreed_at,o.master_workflow_stage,o.report_uploaded_at,o.report_review_status]);let flow=detail.querySelector('.mwv2DispatcherFlow');if(flow?.dataset.sig===sig)return;if(!flow){flow=document.createElement('div');flow.className='mwv2DispatcherFlow';const anchor=detail.querySelector('.dbFlags,.ddFlags,.dbDetailGrid,.ddInfoGrid');if(anchor)anchor.insertAdjacentElement('afterend',flow);else detail.prepend(flow)}flow.dataset.sig=sig;flow.innerHTML=flowHtml(o)}
function decorateOpsBar(){if(!dispatcherMode()||window.innerWidth<1050||String(state?.page||'')!=='orders'||!document.querySelector('.dbBoard'))return;const date=document.getElementById('dispatchBoardDate')?.value||'',orders=(state.orders||[]).filter(o=>!date||String(o.scheduled_date||'').slice(0,10)===date),counts={call:0,agreed:0,road:0,work:0,report:0};for(const o of orders){const s=status(o);if(s==='Нужно позвонить'||s==='Связался'||s==='Звонок отмечен')counts.call++;else if(s==='Договорено')counts.agreed++;else if(s==='В дороге')counts.road++;else if(s==='В работе')counts.work++;else if(s==='Отчёт на проверке'||s==='Отчёт на доработку')counts.report++}const anchor=document.querySelector('.dbV21Tools')||document.querySelector('.dbFilters');if(!anchor)return;let bar=document.querySelector('.mwv2OpsBar');if(!bar){bar=document.createElement('div');bar.className='mwv2OpsBar';anchor.insertAdjacentElement('afterend',bar)}const sig=JSON.stringify([date,counts]);if(bar.dataset.sig===sig)return;bar.dataset.sig=sig;bar.innerHTML=`<b>Этапы мастеров</b><span class="${counts.call?'danger':''}">Связаться: ${counts.call}</span><span>Договорено: ${counts.agreed}</span><span>В дороге: ${counts.road}</span><span>В работе: ${counts.work}</span><span>Отчёт: ${counts.report}</span>`}
function decorateDispatcher(){decorateDispatcherCards();decorateDispatcherDetail();decorateOpsBar()}
function decorate(){queued=false;decorateMasterModal();decorateToday();decorateDispatcher()}
function schedule(){if(queued)return;queued=true;requestAnimationFrame(decorate)}
new MutationObserver(schedule).observe(document.documentElement,{childList:true,subtree:true});
window.addEventListener('resize',schedule);
setTimeout(schedule,0);
const style=document.createElement('style');
style.textContent=`.bosMasterAgreementBtn,.bosMasterAgreementModalBtn{display:none!important}.bosMasterTodayWorkflow .bosMwTodayStage{display:none!important}.bosMasterWorkflow[data-bos-v115="1"]{padding:14px}.mwv2Head{display:flex;justify-content:space-between;align-items:flex-start;gap:10px}.mwv2Head small{font-size:10px;font-weight:800;letter-spacing:.08em;color:var(--muted,#91a3b7)}.mwv2Head h3{margin:3px 0 0}.mwv2Head>span{font-size:11px;font-weight:800;padding:5px 8px;border-radius:999px;background:rgba(37,99,235,.10);color:#60a5fa}.mwv2Steps{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:3px;margin:15px 0}.mwv2Step{position:relative;display:grid;justify-items:center;gap:4px;text-align:center;min-width:0}.mwv2Step:before{content:'';position:absolute;top:6px;left:-50%;right:50%;height:2px;background:rgba(127,127,127,.18)}.mwv2Step:first-child:before{display:none}.mwv2Step i{width:12px;height:12px;border-radius:50%;z-index:1;background:rgba(127,127,127,.28)}.mwv2Step.done i,.mwv2Step.done:before{background:#2563eb}.mwv2Step.current i{box-shadow:0 0 0 4px rgba(37,99,235,.15)}.mwv2Step b{font-size:8px;line-height:1.15}.mwv2Step small{font-size:7px;color:var(--muted,#91a3b7)}.mwv2Actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.mwv2Actions>*{min-height:44px;box-sizing:border-box}.mwv2CallLink{display:flex;align-items:center;justify-content:center;text-decoration:none}.mwv2NoPhone{grid-column:1/-1;padding:10px;border:1px solid rgba(220,38,38,.25);border-radius:10px}.mwv2AgreementSummary,.mwv2Review{grid-column:1/-1;display:flex;flex-direction:column;gap:3px;padding:9px 10px;border:1px solid rgba(127,127,127,.16);border-radius:10px}.mwv2AgreementSummary span,.mwv2Review span{font-size:11px;color:var(--muted,#91a3b7)}.mwv2Review.rejected{border-color:rgba(220,38,38,.3)}.mwv2ReportBtn{grid-column:1/-1}.mwv2DispatcherFlow{margin:10px 0;padding:10px;border:1px solid rgba(127,127,127,.15);border-radius:11px}.mwv2DispatcherFlow>b{display:block;margin-bottom:7px;font-size:11px}.mwv2DispatcherFlow>div{display:flex;gap:4px;flex-wrap:wrap}.mwv2DispatcherFlow span{font-size:9px;padding:4px 6px;border-radius:999px;background:rgba(127,127,127,.1);color:var(--muted,#91a3b7)}.mwv2DispatcherFlow span.done{background:rgba(37,99,235,.11);color:#60a5fa}.mwv2DispatcherFlow span.current{outline:1px solid rgba(96,165,250,.55);color:inherit}.mwv2OpsBar{display:flex;gap:7px;align-items:center;flex-wrap:wrap;margin:0 0 12px;padding:8px 10px;border:1px solid rgba(127,127,127,.16);border-radius:12px;background:var(--card,#fff)}.mwv2OpsBar b{margin-right:auto}.mwv2OpsBar span,.mwv2MobileStage,.mwv2FieldStageChip,.mwv2TodayStage{font-size:10px;padding:4px 7px;border-radius:999px;background:rgba(37,99,235,.08);color:#60a5fa}.mwv2OpsBar span.danger,.mwv2FieldStageChip.danger{background:rgba(220,38,38,.09);color:#f87171}.mwv2MobileStage,.mwv2FieldStageChip,.mwv2TodayStage{display:inline-flex;width:max-content;max-width:100%}@media(max-width:600px){.mwv2Steps{grid-template-columns:repeat(3,1fr);row-gap:12px}.mwv2Step:nth-child(4):before{display:none}.mwv2Actions{grid-template-columns:1fr}.mwv2AgreementSummary,.mwv2Review,.mwv2ReportBtn,.mwv2NoPhone{grid-column:auto}.mwv2Actions>*{min-height:48px}}`;
document.head.appendChild(style);
})();


